{"command": "python3 -u -c "
import urllib.request, ssl, json, time
ctx = ssl.create_default_context(); ctx.check_hostname=False; ctx.verify_mode=ssl.CERT_NONE
for i in range(5):
    try:
        req = urllib.request.Request('https://api.ivxholding.com/health', headers={'Accept':'application/json'})
        resp = urllib.request.urlopen(req, timeout=20, context=ctx)
        body = json.loads(resp.read().decode())
        print(f'HEALTH {i}: {body.get(\"status\")} commit={body.get(\"commitShort\")} apk={body.get(\"apkReleaseV159\")}')
        if body.get('status') == 'healthy':
            break
    except Exception as e:
        print(f'HEALTH {i}: ERROR {str(e)[:100]}')
    time.sleep(5)
""}
